	async function deleteCurrentPicture(uid, field) {
		if (meta.config['profile:keepAllUserImages']) {
			return;
		}
		const value = await User.getUserField(uid, field);
		await deleteLocalProfileUrl(value);
	}

	const imageExtensions = ['png', 'jpeg', 'jpg', 'bmp'];
	const profileFolder = () => path.join(nconf.get('upload_path'), 'profile');

	function localProfilePath(url) {
		const relativePath = nconf.get('relative_path') || '';
		const prefix = `${relativePath}/assets/uploads/profile/`;
		// Local uploads are stored without relative_path; public URLs can include it.
		if (typeof url === 'string' && url.startsWith('/assets/uploads/profile/')) {
			url = relativePath + url;
		}
		if (typeof url !== 'string' || !url.startsWith(prefix)) {
			return false;
		}
		const name = url.slice(prefix.length);
		if (!name || name === '.' || name === '..' || path.basename(name) !== name ||
			name.includes('\\') || !imageExtensions.includes(path.extname(name).slice(1).toLowerCase())) {
			return false;
		}
		return path.join(profileFolder(), name);
	}

	async function unlinkIfPresent(filename) {
		try {
			await fs.promises.unlink(filename);
		} catch (err) {
			if (err.code !== 'ENOENT') {
				throw err;
			}
		}
	}

	async function deleteLocalProfileUrl(url) {
		const filename = localProfilePath(url);
		if (filename) {
			await unlinkIfPresent(filename);
		}
	}

	async function profilePaths(uid, type) {
		if (!/^[1-9]\d*$/.test(String(uid)) || !Number.isSafeInteger(Number(uid))) {
			return [];
		}
		let names;
		try {
			names = await fs.promises.readdir(profileFolder());
		} catch (err) {
			if (err.code === 'ENOENT') {
				return [];
			}
			throw err;
		}
		const pattern = profileNamePattern(uid, type);
		return names.filter(name => pattern.test(name)).map(name => path.join(profileFolder(), name));
	}

	function profileNamePattern(uid, type) {
		return new RegExp(`^${uid}-profile${type}(?:-\\d+)?\\.(?:${imageExtensions.join('|')})$`, 'i');
	}

	User.getLocalCoverPath = async uid => (await profilePaths(uid, 'cover'))[0] || false;
	User.getLocalAvatarPath = async uid => (await profilePaths(uid, 'avatar'))[0] || false;

	async function removeProfileFiles(uid, type, url) {
		const paths = await profilePaths(uid, type);
		const fromUrl = localProfilePath(url);
		if (fromUrl && profileNamePattern(uid, type).test(path.basename(fromUrl))) {
			paths.push(fromUrl);
		}
		await Promise.all([...new Set(paths)].map(unlinkIfPresent));
	}

	function validateUpload(data, maxSize, allowedTypes) {
		if (!data.imageData) {
			throw new Error('[[error:invalid-data]]');
		}
		const size = image.sizeFromBase64(data.imageData);
		if (size > maxSize * 1024) {
			throw new Error(`[[error:file-too-big, ${maxSize}]]`);
		}

		const type = image.mimeFromBase64(data.imageData);
		if (!type || !allowedTypes.includes(type)) {
			throw new Error('[[error:invalid-image]]');
		}
	}

	async function convertToPNG(path) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
